/**
 * Create / edit a custom EOL product, and add a cycle to one.
 *
 * Shared by the card's End of Life section (create a product on the fly when
 * endoflife.date has nothing for it, add a missing cycle) and the admin grid
 * in Settings → EOL. A product is created with its first cycles in one
 * request, so the card flow can pick the new cycle straight away. The key a
 * card link stores is generated by the server from the title: nobody sees it
 * here.
 */
import { useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import Alert from "@mui/material/Alert";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import DialogTitle from "@mui/material/DialogTitle";
import Divider from "@mui/material/Divider";
import FormControl from "@mui/material/FormControl";
import FormHelperText from "@mui/material/FormHelperText";
import IconButton from "@mui/material/IconButton";
import InputLabel from "@mui/material/InputLabel";
import MenuItem from "@mui/material/MenuItem";
import Select from "@mui/material/Select";
import type { MenuProps } from "@mui/material/Menu";
import Stack from "@mui/material/Stack";
import TextField from "@mui/material/TextField";
import Tooltip from "@mui/material/Tooltip";
import Typography from "@mui/material/Typography";
import { api } from "@/api/client";
import AiSuggestPanel, { type AiApplyPayload } from "@/components/AiSuggestPanel";
import { DateField } from "@/components/DateField";
import MaterialSymbol from "@/components/MaterialSymbol";
import { useAiStatus } from "@/hooks/useAiStatus";
import { useLatestRequest } from "@/hooks/useLatestRequest";
import {
  isValidEolLink,
  milestoneMode,
  milestoneValue,
  type MilestoneKind,
  type MilestoneMode,
} from "@/lib/eolCustom";
import type {
  AiSuggestResponse,
  EolCustomCycle,
  EolCustomCycleInput,
  EolCustomProduct,
  EolMilestone,
} from "@/types";

// ── Milestone (EOL / end of support) field ─────────────────────────────────

const MODES: MilestoneMode[] = ["unset", "date", "ongoing", "ended"];
/** endoflife.date requires an end of life: "unknown" is not an answer there. */
const REQUIRED_MODES: MilestoneMode[] = ["date", "ongoing", "ended"];

/** What a date input needs to show a full date with its calendar button. */
const DATE_MIN_WIDTH = 170;

interface MilestoneFieldProps {
  kind: MilestoneKind;
  value: EolMilestone;
  onChange: (value: EolMilestone) => void;
  size?: "small" | "medium";
  /** Shown under the date when it conflicts with another date of the cycle. */
  error?: string;
  /** Passed to the select's menu (a grid cell editor marks it as its own). */
  menuProps?: Partial<MenuProps>;
  /** No "Unknown" answer: the select opens on a placeholder until one is chosen. */
  required?: boolean;
}

/**
 * A date, or one of the two answers endoflife.date allows when no date is
 * known: still going ("no end announced" / "still supported") or already over.
 *
 * Select and date share a wrapping row: side by side where the row is wide
 * enough for both, the date under the select otherwise (a grid popup), so
 * the date is never squeezed below what it needs to be read.
 */
export function MilestoneField({
  kind,
  value,
  onChange,
  size = "medium",
  error,
  menuProps,
  required = false,
}: MilestoneFieldProps) {
  const { t } = useTranslation("cards");
  // Choosing "On a date" stores nothing until a date is picked, so the stored
  // value alone would read "Unknown" and never show the date field: the
  // choice is remembered here until a date or another answer replaces it.
  const stored = milestoneMode(value, kind);
  const [datePicked, setDatePicked] = useState(stored === "date");
  // A yes/no answer set from outside replaces a pending date choice.
  if (datePicked && (stored === "ended" || stored === "ongoing")) setDatePicked(false);
  const mode: MilestoneMode = stored === "unset" && datePicked ? "date" : stored;
  const label = t(kind === "eol" ? "eol.endOfLife" : "eol.activeSupport");
  const dateLabel = t(kind === "eol" ? "eol.custom.eolOn" : "eol.custom.supportedUntil");
  const modes = required ? REQUIRED_MODES : MODES;
  // A problem that is not about the date (nothing chosen yet) sits under the select.
  const selectError = error && mode !== "date" ? error : undefined;
  return (
    <Box sx={{ display: "flex", flexWrap: "wrap", gap: 1, minWidth: 0 }}>
      <FormControl
        size={size}
        required={required}
        error={!!selectError}
        sx={{ flex: `1 1 ${DATE_MIN_WIDTH}px`, minWidth: DATE_MIN_WIDTH }}
      >
        <InputLabel>{label}</InputLabel>
        <Select
          label={label}
          value={required && mode === "unset" ? "" : mode}
          displayEmpty={required}
          renderValue={
            required
              ? (v) =>
                  v ? (
                    t(`eol.custom.milestone.${kind}.${v}`)
                  ) : (
                    <Typography component="em" color="text.secondary" sx={{ fontSize: "inherit" }}>
                      {t("eol.custom.milestone.choose")}
                    </Typography>
                  )
              : undefined
          }
          onChange={(e) => {
            const next = e.target.value as MilestoneMode;
            setDatePicked(next === "date");
            onChange(milestoneValue(next, kind, typeof value === "string" ? value : ""));
          }}
          inputProps={{ "aria-label": label }}
          MenuProps={menuProps}
        >
          {modes.map((m) => (
            <MenuItem key={m} value={m}>
              {t(`eol.custom.milestone.${kind}.${m}`)}
            </MenuItem>
          ))}
        </Select>
        {selectError && <FormHelperText>{selectError}</FormHelperText>}
      </FormControl>
      {mode === "date" && (
        <DateField
          size={size}
          label={dateLabel}
          value={typeof value === "string" ? value : ""}
          onChange={(v) => onChange(v || null)}
          error={!!error}
          helperText={error}
          sx={{ flex: `1 1 ${DATE_MIN_WIDTH}px`, minWidth: DATE_MIN_WIDTH }}
        />
      )}
    </Box>
  );
}

// ── Cycle fields ───────────────────────────────────────────────────────────

export type CycleDraft = Required<EolCustomCycleInput>;

export const EMPTY_CYCLE: CycleDraft = {
  cycle: "",
  releaseDate: null,
  support: null,
  eol: null,
  latest: null,
  latestReleaseDate: null,
};

/** The fields a cycle problem is shown on. */
export type CycleIssueField = "cycle" | "support" | "eol";

/** Each problem with a cycle, as an i18n key in `cards`, on the field at fault. */
export function cycleIssues(c: CycleDraft): Partial<Record<CycleIssueField, string>> {
  const issues: Partial<Record<CycleIssueField, string>> = {};
  if (!c.cycle.trim()) issues.cycle = "eol.custom.errors.cycleRequired";
  // endoflife.date requires an end of life on every release.
  if (c.eol === null || c.eol === "") issues.eol = "eol.custom.errors.eolRequired";
  const release = c.releaseDate;
  if (release) {
    if (typeof c.eol === "string" && c.eol < release) issues.eol = "eol.custom.errors.eolBeforeRelease";
    if (typeof c.support === "string" && c.support < release)
      issues.support = "eol.custom.errors.supportBeforeRelease";
  }
  return issues;
}

/** The first problem with a cycle, as an i18n key in `cards`, or null. */
export function cycleProblem(c: CycleDraft): string | null {
  const issues = cycleIssues(c);
  return issues.cycle ?? issues.eol ?? issues.support ?? null;
}

/** The body a cycle is sent as — blank text becomes null. */
export function cyclePayload(c: CycleDraft): EolCustomCycleInput {
  return {
    cycle: c.cycle.trim(),
    releaseDate: c.releaseDate || null,
    support: c.support,
    eol: c.eol,
    latest: c.latest?.trim() || null,
    latestReleaseDate: c.latestReleaseDate || null,
  };
}

interface CycleFieldsProps {
  value: CycleDraft;
  onChange: (next: CycleDraft) => void;
  autoFocus?: boolean;
  /** Problems to show, already translated, on the field each concerns. */
  errors?: Partial<Record<CycleIssueField, string>>;
}

export function CycleFields({ value, onChange, autoFocus, errors = {} }: CycleFieldsProps) {
  const { t } = useTranslation("cards");
  const set = <K extends keyof CycleDraft>(key: K, v: CycleDraft[K]) =>
    onChange({ ...value, [key]: v });
  return (
    <Box
      sx={{
        display: "grid",
        gridTemplateColumns: { xs: "1fr", sm: "1fr 1fr" },
        gap: 2,
      }}
    >
      <TextField
        required
        autoFocus={autoFocus}
        label={t("eol.versionCycle")}
        placeholder={t("eol.custom.cyclePlaceholder")}
        value={value.cycle}
        onChange={(e) => set("cycle", e.target.value)}
        error={!!errors.cycle}
        helperText={errors.cycle}
        inputProps={{ maxLength: 100 }}
      />
      <DateField
        label={t("eol.releaseDate")}
        value={value.releaseDate ?? ""}
        onChange={(v) => set("releaseDate", v || null)}
      />
      {/* A milestone is a select plus a date: it takes a whole row so the
          date has the width it needs beside the select. */}
      <Box sx={{ gridColumn: "1 / -1" }}>
        <MilestoneField
          kind="support"
          value={value.support}
          onChange={(v) => set("support", v)}
          error={errors.support}
        />
      </Box>
      <Box sx={{ gridColumn: "1 / -1" }}>
        <MilestoneField
          kind="eol"
          required
          value={value.eol}
          onChange={(v) => set("eol", v)}
          error={errors.eol}
        />
      </Box>
      <TextField
        label={t("eol.latestVersion")}
        placeholder={t("eol.custom.latestPlaceholder")}
        value={value.latest ?? ""}
        onChange={(e) => set("latest", e.target.value)}
        inputProps={{ maxLength: 100 }}
      />
      <DateField
        label={t("eol.latestRelease")}
        value={value.latestReleaseDate ?? ""}
        onChange={(v) => set("latestReleaseDate", v || null)}
      />
    </Box>
  );
}

// ── Product fields (title, link, description + AI description) ─────────────

export interface ProductDraft {
  title: string;
  link: string;
  description: string;
}

export function productDraft(product?: Pick<EolCustomProduct, "title" | "link" | "description"> | null): ProductDraft {
  return {
    title: product?.title ?? "",
    link: product?.link ?? "",
    description: product?.description ?? "",
  };
}

/** Each problem with the product fields, as an i18n key in `cards`. */
export function productDraftIssues(d: ProductDraft): { title?: string; link?: string } {
  const issues: { title?: string; link?: string } = {};
  if (!d.title.trim()) issues.title = "eol.custom.errors.titleRequired";
  if (d.link.trim() !== "" && !isValidEolLink(d.link)) issues.link = "eol.custom.errors.linkInvalid";
  return issues;
}

/** The body the product fields are sent as — blank text becomes null. */
export function productPayload(d: ProductDraft) {
  return {
    title: d.title.trim(),
    link: d.link.trim() || null,
    description: d.description.trim() || null,
  };
}

interface ProductFieldsProps {
  value: ProductDraft;
  onChange: (next: ProductDraft) => void;
  disabled?: boolean;
  autoFocus?: boolean;
}

/**
 * The product's own fields, with an AI-suggested description when AI
 * suggestions are on. Shared by the create dialog and the admin panel.
 */
export function ProductFields({ value, onChange, disabled, autoFocus }: ProductFieldsProps) {
  const { t } = useTranslation(["cards", "common"]);
  const issues = productDraftIssues(value);
  const set = <K extends keyof ProductDraft>(key: K, v: ProductDraft[K]) =>
    onChange({ ...value, [key]: v });

  // ── AI description ──────────────────────────────────────────────────
  const { aiStatus } = useAiStatus();
  const aiRequest = useLatestRequest();
  const [aiResponse, setAiResponse] = useState<AiSuggestResponse | null>(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState("");
  // A product is not a card type: the switch and the provider are what gate
  // it, and `enabled` already folds in the caller's own permission.
  const aiAvailable = !disabled && aiStatus.enabled && aiStatus.configured;

  const suggestDescription = () =>
    aiRequest.run(async ({ isCurrent }) => {
      setAiLoading(true);
      setAiError("");
      setAiResponse(null);
      try {
        const res = await api.post<AiSuggestResponse>("/ai/suggest-eol-product", {
          name: value.title.trim(),
          link: value.link.trim() || undefined,
        });
        if (!isCurrent()) return;
        setAiResponse(res);
      } catch (err) {
        if (!isCurrent()) return;
        setAiError(err instanceof Error ? err.message : t("common:errors.generic"));
      } finally {
        if (isCurrent()) setAiLoading(false);
      }
    });

  const applySuggestion = (payload: AiApplyPayload) => {
    if (payload.description) set("description", payload.description);
    setAiResponse(null);
  };

  return (
    <Stack spacing={2}>
      <TextField
        required
        autoFocus={autoFocus}
        disabled={disabled}
        label={t("eol.custom.productTitle")}
        value={value.title}
        onChange={(e) => set("title", e.target.value)}
        inputProps={{ maxLength: 200 }}
      />
      <TextField
        disabled={disabled}
        label={t("eol.custom.productLink")}
        placeholder={t("eol.custom.linkPlaceholder")}
        value={value.link}
        onChange={(e) => set("link", e.target.value)}
        error={!!issues.link}
        helperText={issues.link ? t(issues.link) : undefined}
        inputProps={{ maxLength: 500 }}
      />
      <TextField
        multiline
        minRows={2}
        disabled={disabled}
        label={t("eol.custom.productDescription")}
        value={value.description}
        onChange={(e) => set("description", e.target.value)}
        inputProps={{ maxLength: 5000 }}
      />
      {aiAvailable && value.title.trim().length >= 2 && !aiResponse && !aiLoading && (
        <Box>
          {/* describeChild: the tooltip describes the button, and the
              visible label stays its accessible name (WCAG 2.5.3). */}
          <Tooltip title={t("eol.custom.aiTooltip")} describeChild>
            <Button
              size="small"
              variant="outlined"
              onClick={suggestDescription}
              startIcon={<MaterialSymbol icon="auto_awesome" size={16} />}
              sx={{ textTransform: "none" }}
            >
              {t("common:ai.suggestButton")}
            </Button>
          </Tooltip>
        </Box>
      )}
      {(aiLoading || aiError || aiResponse) && (
        <AiSuggestPanel
          response={aiResponse}
          loading={aiLoading}
          error={aiError}
          onApply={applySuggestion}
          onDismiss={() => {
            setAiResponse(null);
            setAiError("");
            setAiLoading(false);
          }}
        />
      )}
    </Stack>
  );
}

// ── Product dialog ─────────────────────────────────────────────────────────

interface ProductDialogProps {
  open: boolean;
  onClose: () => void;
  onSaved: (product: EolCustomProduct) => void;
  /** Edit this product's title, link and description; create when absent. */
  product?: EolCustomProduct | null;
  /** Create mode: what the user typed when nothing matched. */
  initialTitle?: string;
}

/** Remounted per opening (see the wrapper) so every opening starts fresh. */
function ProductDialogBody({ onClose, onSaved, product, initialTitle = "" }: ProductDialogProps) {
  const { t } = useTranslation(["cards", "common"]);
  const editing = !!product;
  const [draft, setDraft] = useState<ProductDraft>(() =>
    product ? productDraft(product) : { ...productDraft(null), title: initialTitle.trim() },
  );
  const [cycles, setCycles] = useState<CycleDraft[]>(editing ? [] : [{ ...EMPTY_CYCLE }]);
  // Rows are keyed by a stable id, never their index: a field's own state
  // (MilestoneField's pending date choice) must not slide onto the next row
  // when one is removed. A row's problems show once it has been edited, so
  // an empty first row does not open the dialog with a warning.
  const nextRowId = useRef(1);
  const [rowIds, setRowIds] = useState<number[]>(editing ? [] : [0]);
  const [touchedRows, setTouchedRows] = useState<Set<number>>(new Set());
  const [focusRowId, setFocusRowId] = useState<number | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const productProblem = Object.keys(productDraftIssues(draft)).length > 0;
  const cycleNames = cycles.map((c) => c.cycle.trim()).filter(Boolean);
  const duplicateCycle = new Set(cycleNames).size !== cycleNames.length;
  const issuesByRow = cycles.map(cycleIssues);
  const anyCycleProblem = issuesByRow.some((issues) => Object.keys(issues).length > 0);
  const canSave = !saving && !productProblem && !duplicateCycle && !anyCycleProblem;

  const save = async () => {
    setSaving(true);
    setError("");
    try {
      const body = productPayload(draft);
      const saved = editing
        ? await api.patch<EolCustomProduct>(
            `/eol/custom-products/${encodeURIComponent(product!.key)}`,
            body,
          )
        : await api.post<EolCustomProduct>("/eol/custom-products", {
            ...body,
            cycles: cycles.map(cyclePayload),
          });
      onSaved(saved);
    } catch (e) {
      setError(e instanceof Error ? e.message : t("common:errors.generic"));
      setSaving(false);
    }
  };

  const touch = (rowId: number) =>
    setTouchedRows((prev) => (prev.has(rowId) ? prev : new Set(prev).add(rowId)));

  return (
    <>
      <DialogTitle>
        {editing ? t("eol.custom.editTitle") : t("eol.custom.createTitle")}
      </DialogTitle>
      <DialogContent>
        {!editing && (
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2, mt: 0.5 }}>
            {t("eol.custom.createIntro")}
          </Typography>
        )}
        {error && (
          <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError("")}>
            {error}
          </Alert>
        )}
        <Box sx={{ mt: 1 }}>
          <ProductFields value={draft} onChange={setDraft} autoFocus />
        </Box>

        {!editing && (
          <>
            <Divider sx={{ my: 2 }} />
            <Typography variant="subtitle2" sx={{ mb: 2 }}>
              {t("eol.custom.cyclesHeading")}
            </Typography>
            <Stack spacing={2} divider={<Divider flexItem />}>
              {cycles.map((c, i) => {
                const rowId = rowIds[i];
                const shown = touchedRows.has(rowId) ? issuesByRow[i] : {};
                const errors = Object.fromEntries(
                  Object.entries(shown).map(([field, key]) => [field, t(key)]),
                ) as Partial<Record<CycleIssueField, string>>;
                return (
                  <Box key={rowId} sx={{ display: "flex", gap: 1, alignItems: "flex-start" }}>
                    <Box sx={{ flex: 1, minWidth: 0 }}>
                      <CycleFields
                        value={c}
                        autoFocus={rowId === focusRowId}
                        errors={errors}
                        onChange={(next) => {
                          touch(rowId);
                          setCycles((prev) => prev.map((p, j) => (j === i ? next : p)));
                        }}
                      />
                    </Box>
                    {cycles.length > 1 && (
                      <Tooltip title={t("eol.custom.removeCycle")}>
                        <IconButton
                          size="small"
                          aria-label={t("eol.custom.removeCycle")}
                          onClick={() => {
                            setCycles((prev) => prev.filter((_, j) => j !== i));
                            setRowIds((prev) => prev.filter((_, j) => j !== i));
                          }}
                        >
                          <MaterialSymbol icon="delete" size={18} />
                        </IconButton>
                      </Tooltip>
                    )}
                  </Box>
                );
              })}
            </Stack>
            <Button
              size="small"
              sx={{ mt: 1.5 }}
              startIcon={<MaterialSymbol icon="add" size={16} />}
              onClick={() => {
                const id = nextRowId.current++;
                setCycles((prev) => [...prev, { ...EMPTY_CYCLE }]);
                setRowIds((prev) => [...prev, id]);
                setFocusRowId(id);
              }}
            >
              {t("eol.custom.addCycleRow")}
            </Button>
            {duplicateCycle && (
              <Alert severity="warning" sx={{ mt: 1.5 }}>
                {t("eol.custom.errors.duplicateCycle")}
              </Alert>
            )}
          </>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={saving}>
          {t("common:actions.cancel")}
        </Button>
        <Button variant="contained" onClick={save} disabled={!canSave}>
          {editing ? t("common:actions.save") : t("eol.custom.create")}
        </Button>
      </DialogActions>
    </>
  );
}

export default function CustomEolProductDialog(props: ProductDialogProps) {
  return (
    <Dialog open={props.open} onClose={props.onClose} maxWidth="sm" fullWidth disableRestoreFocus>
      {props.open && <ProductDialogBody {...props} />}
    </Dialog>
  );
}

// ── Add-cycle dialog ───────────────────────────────────────────────────────

interface CycleDialogProps {
  open: boolean;
  onClose: () => void;
  onSaved: (cycle: EolCustomCycle) => void;
  productKey: string;
  productLabel: string;
}

function CycleDialogBody({ onClose, onSaved, productKey, productLabel }: CycleDialogProps) {
  const { t } = useTranslation(["cards", "common"]);
  const [cycle, setCycle] = useState<CycleDraft>({ ...EMPTY_CYCLE });
  const [touched, setTouched] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const issues = cycleIssues(cycle);
  const problem = Object.keys(issues).length > 0;
  const errors = touched
    ? (Object.fromEntries(Object.entries(issues).map(([f, k]) => [f, t(k)])) as Partial<
        Record<CycleIssueField, string>
      >)
    : {};

  const save = async () => {
    setSaving(true);
    setError("");
    try {
      const saved = await api.post<EolCustomCycle>(
        `/eol/custom-products/${encodeURIComponent(productKey)}/cycles`,
        cyclePayload(cycle),
      );
      onSaved(saved);
    } catch (e) {
      setError(e instanceof Error ? e.message : t("common:errors.generic"));
      setSaving(false);
    }
  };

  return (
    <>
      <DialogTitle>{t("eol.custom.addCycleTitle", { product: productLabel })}</DialogTitle>
      <DialogContent>
        {error && (
          <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError("")}>
            {error}
          </Alert>
        )}
        <Box sx={{ mt: 1 }}>
          <CycleFields
            value={cycle}
            autoFocus
            errors={errors}
            onChange={(next) => {
              setTouched(true);
              setCycle(next);
            }}
          />
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={saving}>
          {t("common:actions.cancel")}
        </Button>
        <Button variant="contained" onClick={save} disabled={saving || problem}>
          {t("eol.custom.addCycle")}
        </Button>
      </DialogActions>
    </>
  );
}

export function CustomEolCycleDialog(props: CycleDialogProps) {
  return (
    <Dialog open={props.open} onClose={props.onClose} maxWidth="sm" fullWidth disableRestoreFocus>
      {props.open && <CycleDialogBody {...props} />}
    </Dialog>
  );
}
